# Generated by Claudian.
"""Serialises PortAudio initialisation across threads.

THE CRASH
---------
    zsh: segmentation fault  python3 run.py

Jarvis opens audio from two threads:

    jarvis-tts    ElevenLabs playback  -> pyaudio.PyAudio()
    jarvis-audio  microphone capture   -> sr.Microphone() -> pyaudio.PyAudio()

Both end up in PortAudio's `Pa_Initialize()`, which is **not thread-safe**.
Called concurrently it corrupts the internal host-API table and the process
dies with SIGSEGV before any Python traceback can be produced — which is why
the crash appeared with no error message.

It is a race, so it is intermittent: in one observed run the greeting and the
microphone opened in the same second and it crashed; the next two runs the
greeting finished first and survived. Intermittent crashes are worse than
consistent ones, because they look like bad luck rather than a bug.

THE FIX
-------
One process-wide lock that every audio-device open must hold. Cheap: it is
only contended during initialisation, never during streaming.
"""

from __future__ import annotations

import threading

# Module-level so both the capture and playback paths share one lock.
portaudio_lock = threading.RLock()
